// Notebook ink is separate from answer input. No recognition or scoring runs here.
export class MathBoard{
 constructor(host,{ask=async()=>true,state=null,onChange=()=>{},canDraw=()=>true}={}){this.host=host;this.canDraw=canDraw;this.ask=ask;this.onChange=onChange;this.state=state||{strokes:[],redo:[],paper:'grid',zoom:1,offset:{x:0,y:0}};this.tool='pen';this.color='#244772';this.size=4;this.active=new Map();this.disposed=false;host.innerHTML=`<div class="mq-tools" role="toolbar" aria-label="Writing tools"><select aria-label="Writing tool" data-tool><option value="pen">✎ Pen</option><option value="eraser">Eraser</option><option value="pan">✥ Move paper</option><option value="line">Straight line</option><option value="rect">Rectangle</option><option value="circle">Ellipse</option><option value="triangle">Triangle</option><option value="ruler">Ruler</option></select><input data-color type="color" aria-label="Ink color" value="#244772"><select data-size aria-label="Pen or eraser size"><option value="4">Fine</option><option value="9">Medium</option><option value="24">Wide eraser</option><option value="45">Large eraser</option></select><button data-undo aria-label="Undo drawing">↶</button><button data-redo aria-label="Redo drawing">↷</button><button data-clear>Clear</button><select data-paper aria-label="Paper style"><option value="grid">Grid</option><option value="lined">Lined</option><option value="blank">Blank</option></select><button data-minus aria-label="Zoom out">−</button><output data-zoom>100%</output><button data-plus aria-label="Zoom in">+</button><button data-fraction>Fraction space</button><button data-home>Top of paper</button><button data-expand>Expand paper</button></div><div class="mq-paper"><canvas class="mq-paper-grid" aria-hidden="true"></canvas><canvas class="mq-ink" aria-label="Show your work. Draw here with touch, stylus or mouse."></canvas><span class="mq-paper-label">SHOW YOUR WORK · answer separately</span></div>`;this.canvas=host.querySelector('.mq-ink');this.grid=host.querySelector('.mq-paper-grid');this.c=this.canvas.getContext('2d');this.gc=this.grid.getContext('2d');const q=s=>host.querySelector(s);q('[data-tool]').onchange=e=>{this.tool=e.target.value;};q('[data-color]').oninput=e=>{this.color=e.target.value;};q('[data-size]').onchange=e=>this.size=+e.target.value;q('[data-paper]').value=this.state.paper;q('[data-paper]').onchange=e=>{this.state.paper=e.target.value;this.draw();};q('[data-undo]').onclick=()=>{this.cancel();if(this.state.strokes.length)this.state.redo.push(this.state.strokes.pop());this.draw();};q('[data-redo]').onclick=()=>{this.cancel();if(this.state.redo.length)this.state.strokes.push(this.state.redo.pop());this.draw();};q('[data-clear]').onclick=async()=>{if(await this.ask('Clear this workspace? Your final answer will stay.')){this.cancel();this.state.strokes=[];this.state.redo=[];this.draw();}};q('[data-minus]').onclick=()=>this.zoom(.8);q('[data-plus]').onclick=()=>this.zoom(1.25);q('[data-fraction]').onclick=()=>{this.cancel();this.state.offset={x:0,y:1200};this.draw();};q('[data-home]').onclick=()=>{this.cancel();this.state.offset={x:0,y:0};this.draw();};q('[data-expand]').onclick=()=>{host.classList.toggle('mq-expanded');q('[data-expand]').textContent=host.classList.contains('mq-expanded')?'Close expanded paper':'Expand paper';this.resize();};this.down=e=>{if(!this.canDraw())return;if(e.button!==undefined&&e.button!==0)return;e.preventDefault();e.stopPropagation();this.canvas.setPointerCapture(e.pointerId);const p=this.point(e);this.active.set(e.pointerId,{tool:this.tool,color:this.color,size:this.size,points:[p],last:{x:e.clientX,y:e.clientY}});this.draw();};this.move=e=>{if(!this.canDraw()){this.cancel();return;}const s=this.active.get(e.pointerId);if(!s)return;e.preventDefault();if(s.tool==='pan'){this.state.offset.x-=(e.clientX-s.last.x)/this.state.zoom;this.state.offset.y-=(e.clientY-s.last.y)/this.state.zoom;this.clamp();s.last={x:e.clientX,y:e.clientY};}else{const events=e.getCoalescedEvents?.();for(const ev of events?.length?events:[e]){const p=this.point(ev);if(s.tool==='pen'||s.tool==='eraser'){if(s.points.length<16000)s.points.push(p);}else s.points[1]=p;}}this.draw();};this.up=e=>{const s=this.active.get(e.pointerId);if(!s)return;e.preventDefault();e.stopPropagation();this.active.delete(e.pointerId);if(e.type!=='pointercancel'&&e.type!=='lostpointercapture'&&this.canDraw()&&s.tool!=='pan'){this.state.strokes.push({tool:s.tool,color:s.color,size:s.size,points:s.points});this.state.redo=[];this.onChange(this.state);}if(this.canvas.hasPointerCapture?.(e.pointerId))this.canvas.releasePointerCapture(e.pointerId);this.draw();};this.canvas.addEventListener('pointerdown',this.down);this.canvas.addEventListener('pointermove',this.move);this.canvas.addEventListener('pointerup',this.up);this.canvas.addEventListener('pointercancel',this.up);this.canvas.addEventListener('lostpointercapture',this.up);this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(host.querySelector('.mq-paper'));this.resize();}
 clamp(){this.state.offset.x=Math.max(0,Math.min(1600-this.w/this.state.zoom,this.state.offset.x));this.state.offset.y=Math.max(0,Math.min(2400-this.h/this.state.zoom,this.state.offset.y));}
 point(e){const r=this.canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/this.state.zoom+this.state.offset.x,y:(e.clientY-r.top)/this.state.zoom+this.state.offset.y};}
 resize(){if(this.disposed)return;const r=this.canvas.parentElement.getBoundingClientRect();this.w=Math.max(200,r.width);this.h=Math.max(240,r.height);const dpr=Math.min(2,window.devicePixelRatio||1);for(const c of [this.canvas,this.grid]){c.width=Math.round(this.w*dpr);c.height=Math.round(this.h*dpr);c.getContext('2d').setTransform(dpr,0,0,dpr,0,0);}this.draw();}
 zoom(factor){this.cancel();const old=this.state.zoom;this.state.zoom=Math.max(.5,Math.min(2,old*factor));this.clamp();this.draw();}
 stroke(c,s){const p=s.points;if(!p.length||s.tool==='pan')return;c.save();c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=s.size;c.lineJoin='round';c.lineCap='round';if(s.tool==='eraser')c.globalCompositeOperation='destination-out';c.beginPath();if(['pen','eraser'].includes(s.tool)){c.moveTo(p[0].x,p[0].y);if(p.length===1){c.arc(p[0].x,p[0].y,s.size/2,0,Math.PI*2);c.fill();}else{for(let i=1;i<p.length-1;i++)c.quadraticCurveTo(p[i].x,p[i].y,(p[i].x+p[i+1].x)/2,(p[i].y+p[i+1].y)/2);c.lineTo(p.at(-1).x,p.at(-1).y);c.stroke();}}else{const a=p[0],b=p[1]||a;if(s.tool==='rect')c.rect(a.x,a.y,b.x-a.x,b.y-a.y);else if(s.tool==='circle')c.ellipse((a.x+b.x)/2,(a.y+b.y)/2,Math.abs(b.x-a.x)/2,Math.abs(b.y-a.y)/2,0,0,Math.PI*2);else if(s.tool==='triangle'){c.moveTo((a.x+b.x)/2,a.y);c.lineTo(b.x,b.y);c.lineTo(a.x,b.y);c.closePath();}else{c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);}c.stroke();if(s.tool==='ruler'){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len;c.lineWidth=1.5;c.font='12px sans-serif';for(let k=0;k<=len;k+=20){const x=a.x+ux*k,y=a.y+uy*k,major=k%100===0;c.beginPath();c.moveTo(x,y);c.lineTo(x-uy*(major?16:8),y+ux*(major?16:8));c.stroke();if(major)c.fillText(String(k/20),x-uy*28,y+ux*28);}}}c.restore();}
 draw(){if(this.disposed||!this.w)return;const {zoom:z,offset:o,paper}=this.state;this.gc.clearRect(0,0,this.w,this.h);this.c.clearRect(0,0,this.w,this.h);for(const c of [this.gc,this.c]){c.save();c.scale(z,z);c.translate(-o.x,-o.y);}const c=this.gc;c.fillStyle='#fffdf6';c.fillRect(0,0,1600,2400);if(paper!=='blank'){c.strokeStyle='#93bdd64d';c.lineWidth=1;const gap=paper==='lined'?40:28;c.beginPath();for(let y=0;y<=2400;y+=gap){c.moveTo(0,y);c.lineTo(1600,y);}if(paper==='grid')for(let x=0;x<=1600;x+=gap){c.moveTo(x,0);c.lineTo(x,2400);}c.stroke();}c.fillStyle='#55728e';c.font='17px sans-serif';c.fillText('FRACTION SPACE · draw bars, equal pieces and number lines',30,1240);c.strokeStyle='#b7a2db';c.lineWidth=2;c.strokeRect(25,1260,1450,920);for(let i=1;i<4;i++){c.beginPath();c.moveTo(25,1260+i*230);c.lineTo(1475,1260+i*230);c.stroke();}for(const s of this.state.strokes)this.stroke(this.c,s);for(const s of this.active.values())this.stroke(this.c,s);this.gc.restore();this.c.restore();this.host.querySelector('[data-zoom]').textContent=Math.round(z*100)+'%';this.host.querySelector('[data-undo]').disabled=!this.state.strokes.length;this.host.querySelector('[data-redo]').disabled=!this.state.redo.length;}
 snapshot(){return JSON.parse(JSON.stringify(this.state));}
 cancel(){const ids=[...this.active.keys()];this.active.clear();for(const id of ids)if(this.canvas.hasPointerCapture?.(id))this.canvas.releasePointerCapture(id);this.draw();}
 dispose(){this.cancel();this.disposed=true;this.observer.disconnect();this.active.clear();for(const [ev,fn]of [['pointerdown',this.down],['pointermove',this.move],['pointerup',this.up],['pointercancel',this.up],['lostpointercapture',this.up]])this.canvas.removeEventListener(ev,fn);}
}
